@props([
    'orientation' => 'horizontal',
])

@php
    use Knppy\Ui\Facades\Ui;

    $classes = Ui::classes()
        ->add('flex w-fit items-stretch has-[>[data-slot=button-group]]:gap-2 [&>*]:focus-visible:relative [&>*]:focus-visible:z-10 has-[select[aria-hidden=true]:last-child]:[&>[data-slot=select-trigger]:last-of-type]:rounded-r-md [&>[data-slot=select-trigger]:not([class*=\'w-\'])]:w-fit [&>input]:flex-1')
        ->add($orientation === 'vertical' ? 'flex-col [&>*:not(:first-child)]:rounded-t-none [&>*:not(:first-child)]:border-t-0 [&>*:not(:last-child)]:rounded-b-none' : '[&>*:not(:first-child)]:rounded-l-none [&>*:not(:first-child)]:border-l-0 [&>*:not(:last-child)]:rounded-r-none')
        ->add($attributes['class'] ?? '');
@endphp

<div
    role="group"
    data-slot="button-group"
    data-orientation="{{ $orientation }}"
    {{ $attributes->twMerge(['class' => $classes]) }}
>
    {{ $slot }}
</div>

@props([
    'orientation' => 'vertical',
])

@php
    use Knppy\Ui\Facades\Ui;

    $classes = Ui::classes()
        ->add('bg-input relative m-0! self-stretch data-[orientation=vertical]:h-auto')
        ->add($attributes['class'] ?? '');
@endphp

<x-ui.separator
    data-slot="button-group-separator"
    :orientation="$orientation"
    {{ $attributes->twMerge(['class' => $classes]) }}
/>

@props([
    'is' => 'div',
])

@php
    use Knppy\Ui\Facades\Ui;

    $classes = Ui::classes()
        ->add('flex items-center gap-2 rounded-md border bg-muted px-4 text-sm font-medium shadow-xs [&_svg]:pointer-events-none [&_svg:not([class*=\'size-\'])]:size-4')
        ->add($attributes['class'] ?? '');
@endphp

<{{$is}} {{ $attributes->twMerge(['class' => $classes]) }}>{{ $slot }}</{{$is}}>
